input.command:
cd /work
awk '
{
  # strip comments
  gsub(/<!--.*-->/, "")
  n = split($0, tags, /<\/?[a-zA-Z]/)
  for (i = 2; i <= n; i++) {
    rest = substr(tags[i], 2)
    name = rest; sub(/[^a-zA-Z0-9].*$/, "", name)
    if (tags[i-1] == "<" && substr(rest, length(name)+1, 1) == "/") {
      close_count[name]++
    } else if (tags[i-1] == "</") {
      open_count[name]++
    }
  }
}
END {
  bad = 0
  for (t in open_count) { if (open_count[t] != close_count[t]) { printf "MISMATCH %s: open=%d close=%d\n", t, open_count[t], close_count[t]; bad=1 } }
  for (t in close_count) { if (!(t in open_count)) { printf "EXTRA CLOSE %s\n", t; bad=1 } }
  if (!bad) print "TAGS BALANCED"
}' SystemContext.svg
ls -la SystemContext.svg

